import overcrow from './overcrow.js';
const response = await overcrow.fetch('https://api.warframe.market/v2/items');
if (!response.ok) throw new Error('Catalog unavailable');
const catalog = await response.json();

import overcrow from './overcrow.js';
if (overcrow.runtime.role === 'unavailable') {
  document.querySelector('#status').textContent = 'OverCrow services are not connected.';
}

const time = document.querySelector('#time');
const toggle = document.querySelector('#toggle');
let elapsedMs = 0, startedAt = null;
toggle.onclick = () => {
  if (startedAt === null) startedAt = performance.now();
  else {
    elapsedMs += performance.now() - startedAt;
    startedAt = null;
  }
  toggle.textContent = startedAt === null ? 'Start' : 'Pause';
};
const timer = setInterval(() => {
  const current = elapsedMs + (startedAt === null ? 0 : performance.now() - startedAt);
  time.textContent = `${(current / 1000).toFixed(1)} s`;
}, 100);
window.addEventListener('pagehide', () => clearInterval(timer), { once: true });

import overcrow from './overcrow.js';
const note = document.querySelector('#note');
const save = document.querySelector('#save');
const status = document.querySelector('#status');
try {
  const stored = await overcrow.storage.get('note');
  if (stored !== undefined && typeof stored !== 'string') throw new Error('Invalid note');
  note.value = stored ?? '';
  note.disabled = save.disabled = false;
} catch { status.textContent = 'Could not load the note.'; }
save.onclick = async () => {
  note.disabled = save.disabled = true;
  try {
    await overcrow.storage.set('note', note.value);
    status.textContent = 'Saved';
  } catch { status.textContent = 'Save failed. Your text is still here.'; }
  finally { note.disabled = save.disabled = false; }
};

import overcrow from './overcrow.js';
const output = document.createElement('p');
output.textContent = 'Loading…';
document.body.append(output);
try {
  const game = await overcrow.game.snapshot();
  const id = game.selectedActive ? game.steamAppId : null;
  if (!Number.isSafeInteger(id) || id <= 0) {
    output.textContent = 'No active Steam game.';
  } else {
    const response = await overcrow.fetch(
      `https://api.playervox.com/api/v1/overcrow/games/steam/${id}/score`
    );
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    if (typeof data?.game?.name !== 'string' ||
        (data.score !== null && (!Number.isFinite(data.score) || data.score < 0 || data.score > 100))) {
      throw new Error('Invalid score');
    }
    output.textContent = data.score === null
      ? `${data.game.name} · No ratings yet`
      : `${data.game.name} · ${data.score.toFixed(1)}/100`;
  }
} catch {
  output.textContent = 'Score unavailable. Try again later.';
}

import overcrow from './overcrow.js';
const save = document.querySelector('#save');
const output = document.querySelector('#entries');
const status = document.querySelector('#status');
save.onclick = async () => {
  save.disabled = true;
  try {
    const game = await overcrow.game.snapshot();
    if (!game.selectedActive || game.sessionElapsedMs == null) throw new Error('No session');
    const stored = await overcrow.storage.get('sessions');
    const entries = stored === undefined ? [] : stored;
    if (!Array.isArray(entries) || entries.length > 20 || entries.some(x => typeof x !== 'string')) {
      throw new Error('Invalid session log');
    }
    const entry = `${new Date().toISOString()} · ${Math.floor(game.sessionElapsedMs / 60000)} min`;
    const next = [...entries, entry].slice(-20);
    await overcrow.storage.set('sessions', next);
    output.textContent = next.join('\n');
    status.textContent = 'Saved';
  } catch { status.textContent = 'Could not save this session.'; }
  finally { save.disabled = false; }
};

import type { OvercrowResponse } from './overcrow.js';
type Fetch = (url: string, options?: {
  method?: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  body?: string | ArrayBuffer | ArrayBufferView | null;
}) => Promise<OvercrowResponse>;

import overcrow from './overcrow.js';
const status = document.querySelector('#status');
try {
  status.textContent = 'Loading…';
  const response = await overcrow.fetch('https://api.warframe.market/v2/items');
  if (!response.ok) throw new Error('HTTP ' + response.status);
  const payload = await response.json();
  if (!Array.isArray(payload?.data)) throw new Error('Invalid catalog');
  status.textContent = payload.data.length + ' items available';
} catch (error) {
  status.textContent = 'Catalog unavailable. Try again.';
  console.error(error.code ?? error.message);
}

import overcrow from './overcrow.js';
const snapshot = await overcrow.game.snapshot();
const ms = snapshot.sessionElapsedMs;
document.querySelector('#duration').textContent =
  typeof ms === 'number' ? Math.floor(ms / 60000) + ' min' : 'Session unavailable';

import overcrow from './overcrow.js';
function render(snapshot) {
  const ms = snapshot.sessionElapsedMs;
  document.querySelector('#duration').textContent =
    typeof ms === 'number' ? Math.floor(ms / 60000) + ' min' : 'Session unavailable';
}
const stop = overcrow.game.onSnapshot(render);
render(await overcrow.game.snapshot());
window.addEventListener('pagehide', stop, { once: true });

