import overcrow from './overcrow.js';

const output = document.createElement('output');
document.body.append(output);
const stop = overcrow.fps.onSnapshot(({ status, data }) => {
  output.textContent = status === 'ready' && !data.stale && data.value != null
    ? `${data.value} FPS` : '— FPS';
});
window.addEventListener('pagehide', stop, { once: true });

import overcrow from './overcrow.js';

const cpu = document.createElement('p');
const fps = document.createElement('p');
document.body.append(cpu, fps);

function show(element, snapshot, value, stale, age) {
  const message = value ?? `Measurement unavailable (${snapshot.status})`;
  element.textContent = message + (stale ? ` · stale (${age ?? 'unknown'} ms old)` : '');
}

const stopCpu = overcrow.telemetry.onSnapshot(snapshot => {
  const value = snapshot.data?.normalizedCpuPercentHundredths;
  show(cpu, snapshot, value == null ? null : `${value / 100}% CPU`,
    snapshot.status === 'stale', snapshot.sampleAgeMs);
});
const stopFps = overcrow.fps.onSnapshot(snapshot => {
  const data = snapshot.data;
  show(fps, snapshot, data?.value == null ? null : `${data.value} FPS`,
    snapshot.status === 'stale' || data?.stale === true,
    data?.sampleAgeMs ?? snapshot.sampleAgeMs);
});
window.addEventListener('pagehide', () => { stopCpu(); stopFps(); }, {once: true});

import overcrow from './overcrow.js';

const track = document.createElement('p');
const status = document.createElement('p');
const play = document.createElement('button');
play.textContent = 'Play / pause';
play.disabled = true;
document.body.append(track, status, play);

const stop = overcrow.media.onSnapshot(snapshot => {
  const data = snapshot.data;
  track.textContent = data
    ? `${data.title ?? 'Untitled'} · ${data.artist ?? 'Unknown artist'}`
    : snapshot.status;
  status.textContent = data?.playbackState ?? snapshot.status;
  if (snapshot.status === 'stale') {
    status.textContent += ` · stale (${snapshot.sampleAgeMs ?? 'unknown'} ms old)`;
  }
  play.disabled = snapshot.status !== 'ready' || !data?.actions.playPause;
});
play.addEventListener('click', async () => {
  try {
    status.textContent = (await overcrow.media.playPause()).status;
  } catch (error) {
    status.textContent = error.code ?? 'unavailable';
  }
});
window.addEventListener('pagehide', stop, {once: true});

import overcrow from './overcrow.js';
const state = { count: 0 };
overcrow.runtime.onMessage(async message => {
  if (!message || typeof message !== 'object') return;
  if (message.type === 'increment') state.count += 1;
  if (message.type === 'hello' || message.type === 'increment') {
    await overcrow.runtime.send({ type: 'state', count: state.count });
  }
});

import overcrow from './overcrow.js';
overcrow.runtime.onMessage(message => {
  if (message?.type !== 'state' || !Number.isSafeInteger(message.count)) return;
  document.querySelector('#count').textContent = String(message.count);
});
await overcrow.runtime.send({ type: 'hello' });
document.querySelector('#increment').addEventListener('click', () => {
  overcrow.runtime.send({ type: 'increment' }).catch(console.error);
});

const stop = overcrow.lifecycle.onVisibility(visible => {
  document.body.dataset.visible = String(visible);
  // Pause animations or unnecessary work while hidden.
});

import overcrow from './overcrow.js';

await overcrow.storage.set('settings', { compact: true });
const settings = await overcrow.storage.get('settings');
console.log(settings); // { compact: true }
await overcrow.storage.remove('obsolete-setting');

import overcrow from './overcrow.js';
import en from './locales/en.mjs';
import fr from './locales/fr.mjs';
const messages = { en, fr };
function render(locale) {
  document.querySelector('#status').textContent = (messages[locale] ?? messages.en).ready;
}
const stop = overcrow.locale.onChanged(render);
render(await overcrow.locale.getCurrent());

import overcrow from './overcrow.js';
document.querySelector('#copy').addEventListener('click', async () => {
  const status = document.querySelector('#status');
  try {
    await overcrow.clipboard.writeText('Hello from OverCrow');
    status.textContent = 'Copied';
  } catch {
    status.textContent = 'Copy denied. Try again in interactive mode.';
  }
});
